411:   function render(frame) {
412:     currentZoom = frame.camera.z;
413:     resize();
414:     const centerX = (frame.camera.x - .5) * WORLD * aspect;
415:     const centerZ = (frame.camera.y - .5) * WORLD;
416:     camera.position.set(centerX, 190, centerZ + 92);
417:     camera.lookAt(centerX, 0, centerZ);
418:     camera.rotation.z = 0;
419:     camera.left = -HALF_VIEW * aspect / currentZoom; camera.right = HALF_VIEW * aspect / currentZoom;
420:     camera.top = HALF_VIEW / currentZoom; camera.bottom = -HALF_VIEW / currentZoom; camera.updateProjectionMatrix();
421: 
422:     const live = new Set();
423:     updateFog(frame);
424:     for (const entity of [...frame.buildings, ...frame.units, ...frame.enemies]) {
425:       live.add(entity.id);
426:       let obj = entities.get(entity.id);
427:       if (!obj || obj.userData.kind !== entity.kind || obj.userData.faction !== frame.faction) {
428:         if (obj) { entityRoot.remove(obj); disposeTree(obj); }
429:         obj = buildEntity(entity, frame.faction); entities.set(entity.id, obj); entityRoot.add(obj);
430:       }
431:       const scale = entity.size ? Math.max(.35, entity.size / 70) * 10 : Math.max(.85, entity.radius / 7);
432:       position(obj, entity.x, entity.y);
433:       obj.scale.setScalar(scale);
434:       const moving = entity.move && Math.hypot((entity.move.x - entity.x) * aspect, entity.move.y - entity.y) > .003;
435:       const moveAngle = moving ? Math.atan2(-(entity.move.x - entity.x) * aspect, -(entity.move.y - entity.y)) : null;
436:       const aimAngle = entity.target ? Math.atan2(-(entity.target.x - entity.x) * aspect, -(entity.target.y - entity.y)) : null;
437:       const turret = obj.userData.model.getObjectByName('turret');
438:       // Track actual displacement so AI-driven units and vehicles face their travel direction too.
439:       const previous = obj.userData.lastPosition;
440:       if (previous) {
441:         const dx = (entity.x - previous.x) * aspect, dy = entity.y - previous.y;
442:         if (dx * dx + dy * dy > 1e-8) obj.userData.heading = Math.atan2(-dx, -dy);
443:       }
444:       obj.userData.lastPosition = { x: entity.x, y: entity.y };
445:       // Models are built facing local -Z. Movement takes precedence; stationary combat units face targets.
446:       obj.rotation.y = entity.size ? 0 : (obj.userData.heading ?? moveAngle ?? (aimAngle !== null && !turret ? aimAngle : 0));
447:       const soldiers = obj.userData.model.userData.soldiers;
448:       if (soldiers) {
449:         const stride = moving ? Math.min(1, .45 + (entity.speed || 20) / 55) : 0;
450:         for (const gait of soldiers) {
451:           const swing = Math.sin(frame.time * 10 + gait.phase) * .52 * stride;
452:           for (const leg of gait.legs) leg.mesh.rotation.x = leg.base + swing;
453:           for (const arm of gait.arms) arm.mesh.rotation.x = arm.base - swing * .42;
454:           gait.soldier.position.y = gait.baseY + Math.abs(Math.sin(frame.time * 10 + gait.phase)) * .055 * stride;
455:         }
456:       }
457:       const fogIndex = Math.max(0, Math.min(127, Math.floor(entity.y * 128))) * 128 + Math.max(0, Math.min(127, Math.floor(entity.x * 128)));
458:       obj.visible = entity.hp > 0 && (entity.team === 'blue' || visibleCells[fogIndex] === 1);
459:       obj.userData.selection.visible = entity === frame.selected;
460:       obj.userData.selection.scale.setScalar(entity.size ? 1 : .6);
461:       obj.userData.selection.material.opacity = entity.team === 'blue' ? .9 : .65;
462:       obj.userData.model.rotation.y = 0;
463:       if (turret) turret.rotation.y = aimAngle === null ? 0 : aimAngle - obj.rotation.y;
464:       obj.userData.health.visible = entity.hp < entity.max;
465:       const ratio = Math.max(0, Math.min(1, entity.hp / entity.max));
466:       obj.userData.healthFill.scale.x = ratio;
467:       obj.userData.healthFill.position.x = -(obj.userData.health.userData.width * (1 - ratio)) / 2;
468:       const hopper = obj.getObjectByName('ore hopper');
469:       if (hopper) hopper.material = entity.carry > 0 ? mat('#b6944d') : mat('#756a49');
470:       const vehicle = obj.userData.model.getObjectByName('vehicle');
471:       if (vehicle) vehicle.position.y = entity.kind === 'collector' && entity.harvesting ? Math.sin(frame.time * 2.5) * .08 : 0;
472:     }
473:     for (const [id, obj] of entities) if (!live.has(id)) { entityRoot.remove(obj); disposeTree(obj); entities.delete(id); }
474:     syncResources(frame);
475:     syncEffects(frame);
476:     let ghost = scene.getObjectByName('placement-preview');
477:     if (frame.placement) {
478:       if (!ghost) {
479:         ghost = new THREE.Mesh(new THREE.BoxGeometry(8, 4, 8), new THREE.MeshBasicMaterial({ color: '#c8f05b', wireframe: true, transparent: true, opacity: .8 }));
480:         ghost.name = 'placement-preview'; scene.add(ghost);
481:       }
482:       const pointer = frame.pointer || { x: .5, y: .5 };
483:       position(ghost, pointer.x, pointer.y, 2); ghost.visible = true;
484:     } else if (ghost) ghost.visible = false;
485:     renderer.render(scene, camera);
486:   }
