518:   function syncEffects(frame) {
519:     const key = `${frame.shots.length}:${frame.particles.length}:${Math.floor(frame.time * 10)}`;
520:     if (transientKey === key) return;
521:     transientKey = key;
522:     while (transientRoot.children.length) {
523:       const child = transientRoot.children[0]; transientRoot.remove(child); disposeTree(child);
524:     }
525:     const up = new THREE.Vector3(0, 1, 0);
526:     const addTracer = (from, to, radius, color) => {
527:       const delta = to.clone().sub(from), length = delta.length();
528:       if (length < .025) return;
529:       const tracer = new THREE.Mesh(new THREE.CylinderGeometry(radius * .72, radius, length, 6), basic(color));
530:       tracer.position.copy(from).add(to).multiplyScalar(.5);
531:       tracer.quaternion.setFromUnitVectors(up, delta.normalize());
532:       transientRoot.add(tracer);
533:     };
534:     for (const shot of frame.shots) {
535:       if (!shot.target) continue;
536:       const t = Math.max(0, Math.min(1, 1 - shot.life / shot.max));
537:       const weapon = shot.weapon || (shot.sourceKind === 'tank' ? 'cannon' : shot.sourceKind === 'infantry' ? 'rifle' : 'machinegun');
538:       const height = weapon === 'missile' ? 5.2 : weapon === 'cannon' ? 2.65 : weapon === 'flak' ? 3.15 : weapon === 'autocannon' ? 2.45 : weapon === 'rifle' ? 1.45 : 2.05;
539:       const a = new THREE.Vector3((shot.x - .5) * WORLD * aspect, height, (shot.y - .5) * WORLD);
540:       const progress = t;
541:       const arc = weapon === 'cannon' ? Math.sin(Math.PI * progress) * 3.8 : weapon === 'flak' ? Math.sin(Math.PI * progress) * 2.2 : 0;
542:       const b = new THREE.Vector3((shot.x + (shot.target.x - shot.x) * progress - .5) * WORLD * aspect, height + arc, (shot.y + (shot.target.y - shot.y) * progress - .5) * WORLD);
543:       const direction = b.clone().sub(a).normalize();
544:       const color = shot.color || '#f4d781';
545:       if (weapon === 'cannon') {
546:         const trailStart = b.clone().lerp(a, .22);
547:         addTracer(trailStart, b, .11, '#ffd77a');
548:         const shell = new THREE.Mesh(new THREE.SphereGeometry(.34, 10, 8), mat('#3c3b32', .38, .62));
549:         shell.position.copy(b); shell.scale.set(.9, .8, 1.25); transientRoot.add(shell);
550:         const glint = new THREE.Mesh(new THREE.SphereGeometry(.16, 8, 6), basic('#ffb34e'));
551:         glint.position.copy(b); transientRoot.add(glint);
552:       } else if (weapon === 'missile') {
553:         const trailStart = b.clone().lerp(a, .16);
554:         addTracer(trailStart, b, .16, '#ef9d4c');
555:         const missile = new THREE.Group();
556:         const body = new THREE.Mesh(new THREE.CylinderGeometry(.14, .2, .95, 8), mat('#55564a', .42, .55));
557:         body.rotation.x = Math.PI / 2; missile.add(body);
558:         const nose = new THREE.Mesh(new THREE.ConeGeometry(.15, .34, 8), mat('#c4b58b', .48, .35));
559:         nose.rotation.x = -Math.PI / 2; nose.position.z = -.62; missile.add(nose);
560:         for (let i = 0; i < 4; i++) {
561:           const fin = new THREE.Mesh(new THREE.BoxGeometry(.34, .07, .27), mat('#383b34', .55, .4));
562:           fin.position.set(Math.cos(i * Math.PI / 2) * .19, Math.sin(i * Math.PI / 2) * .19, .31); missile.add(fin);
563:         }
564:         missile.position.copy(b); missile.quaternion.setFromUnitVectors(new THREE.Vector3(0, 0, -1), direction);
565:         transientRoot.add(missile);
566:         const flame = new THREE.Mesh(new THREE.ConeGeometry(.19, .62, 8), basic('#ff7838', .9));
567:         flame.position.copy(b).addScaledVector(direction, -.68);
568:         flame.quaternion.setFromUnitVectors(up, direction.clone().negate()); transientRoot.add(flame);
569:       } else if (weapon === 'flak') {
570:         addTracer(b.clone().lerp(a, .28), b, .095, '#ffb75d');
571:         const shell = new THREE.Mesh(new THREE.SphereGeometry(.23, 9, 7), mat('#51483a', .46, .5));
572:         shell.position.copy(b); transientRoot.add(shell);
573:         const glow = new THREE.Mesh(new THREE.SphereGeometry(.34, 8, 6), basic('#ff9e49', .35));
574:         glow.position.copy(b); transientRoot.add(glow);
575:       } else {
576:         const radius = weapon === 'autocannon' ? .062 : weapon === 'rifle' ? .032 : .048;
577:         const tracerColor = weapon === 'rifle' ? '#f5e4ad' : weapon === 'autocannon' ? '#ffb94e' : color;
578:         addTracer(a, b, radius, tracerColor);
579:         const tip = new THREE.Mesh(new THREE.SphereGeometry(weapon === 'autocannon' ? .13 : .085, 7, 5), basic(tracerColor));
580:         tip.position.copy(b); transientRoot.add(tip);
581:       }
582:     }
583:     for (const particle of frame.particles) {
584:       const mesh = new THREE.Mesh(new THREE.SphereGeometry(.35 + (1 - particle.life / particle.max) * 1.7, 8, 6), basic(particle.color, Math.max(.12, particle.life / particle.max)));
585:       position(mesh, particle.x, particle.y, .8); transientRoot.add(mesh);
586:     }
